function build(index: number): Dict {
  const d: Dict = {};
  for (const [key, values] of Object.entries(TABLE)) d[key] = values[index];
  return d;
}

export const dictionaries: Partial<Record<LangCode, Dict>> = Object.fromEntries(
  ORDER.map((code, i) => [code, build(i)]),
) as Partial<Record<LangCode, Dict>>;
